"""Scoring rules. No I/O here."""


def gc_fraction(sequence):
    if not sequence:
        return 0.0
    hits = sum(1 for base in sequence.upper() if base in "GC")
    return hits / len(sequence)


def score(sequence, target=0.5):
    return round(1.0 - abs(gc_fraction(sequence) - target), 6)

