import unittest

from seqpipe.domain import gc_fraction, score


class Domain(unittest.TestCase):
    def test_gc_fraction_of_an_empty_sequence_is_zero(self):
        self.assertEqual(gc_fraction(""), 0.0)

    def test_gc_fraction_counts_both_cases(self):
        self.assertEqual(gc_fraction("GgCcAT"), 4 / 6)

    def test_score_peaks_at_the_target(self):
        self.assertEqual(score("GCAT", 0.5), 1.0)
        self.assertLess(score("GGGG", 0.5), 1.0)

